INSERT INTO `campaign_templates` (`id`, `broker_id`, `name`, `content`, `category`, `description`, `variables`, `variables_list`, `is_active`, `is_default`, `usage_count`, `created_at`, `updated_at`) VALUES
(1, 2, 'Recordatorio de Pago', 'Hola {{cliente}}, te recordamos que tienes un pago pendiente de ${{monto}} correspondiente a tu póliza {{poliza}}. El vencimiento es el {{vencimiento}}. Para realizar el pago, haz clic aquí: {{enlace}}', 'recordatorios', 'Plantilla para recordar pagos pendientes de pólizas', '\"{\\\"cliente\\\":\\\"Nombre del cliente\\\",\\\"monto\\\":\\\"Monto a pagar\\\",\\\"poliza\\\":\\\"N\\\\u00famero de p\\\\u00f3liza\\\",\\\"vencimiento\\\":\\\"Fecha de vencimiento\\\",\\\"enlace\\\":\\\"Enlace de pago\\\"}\"', '\"[\\\"cliente\\\",\\\"monto\\\",\\\"poliza\\\",\\\"vencimiento\\\",\\\"enlace\\\"]\"', 1, 1, 0, '2025-09-24 08:06:30', '2025-09-24 08:06:30'),
(2, 2, 'Felicitación de Cumpleaños', '¡Feliz cumpleaños {{cliente}}! 🎉 Desde {{empresa}} queremos desearte un día lleno de alegría y prosperidad. Gracias por confiar en nosotros.', 'general', 'Plantilla para felicitar cumpleaños a los clientes', '\"{\\\"cliente\\\":\\\"Nombre del cliente\\\",\\\"empresa\\\":\\\"Nombre de la empresa\\\"}\"', '\"[\\\"cliente\\\",\\\"empresa\\\"]\"', 1, 1, 0, '2025-09-24 08:06:30', '2025-09-24 08:06:30'),
(3, 2, 'Promoción Especial', '¡{{cliente}}! 🎊 Tenemos una {{promocion}} especial para ti. Aprovecha este descuento del {{codigo}} en tu próxima póliza. ¡No te lo pierdas!', 'promociones', 'Plantilla para promociones y descuentos especiales', '\"{\\\"cliente\\\":\\\"Nombre del cliente\\\",\\\"promocion\\\":\\\"Tipo de promoci\\\\u00f3n\\\",\\\"codigo\\\":\\\"C\\\\u00f3digo de descuento\\\"}\"', '\"[\\\"cliente\\\",\\\"promocion\\\",\\\"codigo\\\"]\"', 1, 1, 0, '2025-09-24 08:06:30', '2025-09-24 08:06:30'),
(4, 2, 'Recordatorio de Renovación', 'Hola {{cliente}}, tu póliza {{poliza}} con {{aseguradora}} está próxima a vencer el {{vencimiento}}. Contacta a tu asesor {{asesor}} para renovar y mantener tu protección.', 'recordatorios', 'Plantilla para recordar renovaciones de pólizas', '\"{\\\"cliente\\\":\\\"Nombre del cliente\\\",\\\"poliza\\\":\\\"N\\\\u00famero de p\\\\u00f3liza\\\",\\\"aseguradora\\\":\\\"Nombre de la aseguradora\\\",\\\"vencimiento\\\":\\\"Fecha de vencimiento\\\",\\\"asesor\\\":\\\"Nombre del asesor\\\"}\"', '\"[\\\"cliente\\\",\\\"poliza\\\",\\\"aseguradora\\\",\\\"vencimiento\\\",\\\"asesor\\\"]\"', 1, 1, 0, '2025-09-24 08:06:30', '2025-09-24 08:06:30'),
(5, 2, 'Bienvenida Nuevo Cliente', '¡Bienvenido {{cliente}}! 👋 Gracias por elegir {{empresa}}. Tu póliza {{poliza}} ya está activa. Tu asesor {{asesor}} estará disponible para cualquier consulta.', 'general', 'Plantilla de bienvenida para nuevos clientes', '\"{\\\"cliente\\\":\\\"Nombre del cliente\\\",\\\"empresa\\\":\\\"Nombre de la empresa\\\",\\\"poliza\\\":\\\"N\\\\u00famero de p\\\\u00f3liza\\\",\\\"asesor\\\":\\\"Nombre del asesor\\\"}\"', '\"[\\\"cliente\\\",\\\"empresa\\\",\\\"poliza\\\",\\\"asesor\\\"]\"', 1, 1, 0, '2025-09-24 08:06:30', '2025-09-24 08:06:30'),
(6, 2, 'Actualización de Estado', 'Hola {{cliente}}, queremos informarte que el estado de tu póliza {{poliza}} ha cambiado. Nuevo estado: {{estado}}. Para más detalles, contacta a {{telefono}}.', 'notificaciones', 'Plantilla para notificar cambios de estado en pólizas', '\"{\\\"cliente\\\":\\\"Nombre del cliente\\\",\\\"poliza\\\":\\\"N\\\\u00famero de p\\\\u00f3liza\\\",\\\"estado\\\":\\\"Nuevo estado\\\",\\\"telefono\\\":\\\"Tel\\\\u00e9fono de contacto\\\"}\"', '\"[\\\"cliente\\\",\\\"poliza\\\",\\\"estado\\\",\\\"telefono\\\"]\"', 1, 1, 0, '2025-09-24 08:06:30', '2025-09-24 08:06:30'),
(10, 2, 'En Blanco', '<table style=\"width:100%;background:#f6f6f6;padding:20px\">\n  <tr>\n    <td align=\"center\">\n      <table style=\"width:600px;background:white;border-radius:8px;padding:30px\">\n        <tr>\n          <td>\n            <h2 style=\"margin:0 0 20px;color:#111827;font-size:24px\">Título de tu email</h2>\n            <p style=\"margin:0 0 15px;color:#4b5563;font-size:14px;line-height:1.6\">\n              Escribe tu mensaje aquí. Puedes usar variables como {{nombre}}, {{email}}, {{numero_documento}}.\n            </p>\n          </td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n</table>', 'general', 'Plantilla en blanco lista para personalizar', '\"{\\\"nombre\\\":\\\"Nombre del cliente\\\",\\\"email\\\":\\\"Email del cliente\\\",\\\"numero_documento\\\":\\\"Documento del cliente\\\"}\"', '\"[\\\"nombre\\\",\\\"email\\\",\\\"numero_documento\\\"]\"', 1, 1, 0, '2025-10-03 22:31:24', '2025-10-03 22:31:24'),
(11, 2, 'Bienvenida', '<table style=\"width:100%;background:#f6f6f6;padding:20px\">\n  <tr>\n    <td align=\"center\">\n      <table style=\"width:600px;background:white;border-radius:8px;padding:30px\">\n        <tr>\n          <td>\n            <h1 style=\"margin:0 0 20px;color:#635BFF;font-size:28px;text-align:center\">¡Bienvenido a GURO!</h1>\n            <p style=\"margin:0 0 15px;color:#4b5563;font-size:14px;line-height:1.6\">\n              Hola <strong>{{nombre}}</strong>,\n            </p>\n            <p style=\"margin:0 0 20px;color:#4b5563;font-size:14px;line-height:1.6\">\n              Nos complace darte la bienvenida a nuestra plataforma. Estamos aquí para ayudarte con todas tus necesidades de seguros.\n            </p>\n            <table style=\"margin:20px 0;width:100%\">\n              <tr>\n                <td align=\"center\">\n                  <a href=\"#\" style=\"display:inline-block;padding:12px 30px;background:#635BFF;color:white;text-decoration:none;border-radius:6px;font-weight:600\">Comenzar</a>\n                </td>\n              </tr>\n            </table>\n          </td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n</table>', 'bienvenida', 'Plantilla de bienvenida para nuevos clientes', '\"{\\\"nombre\\\":\\\"Nombre del cliente\\\"}\"', '\"[\\\"nombre\\\"]\"', 1, 1, 0, '2025-10-03 22:31:25', '2025-10-03 22:31:25'),
(12, 2, 'Renovación de Póliza', '<table style=\"width:100%;background:#f6f6f6;padding:20px\">\n  <tr>\n    <td align=\"center\">\n      <table style=\"width:600px;background:white;border-radius:8px;padding:30px\">\n        <tr>\n          <td>\n            <h2 style=\"margin:0 0 20px;color:#111827;font-size:24px\">Renovación de Póliza</h2>\n            <p style=\"margin:0 0 15px;color:#4b5563;font-size:14px;line-height:1.6\">\n              Estimado/a <strong>{{nombre}}</strong>,\n            </p>\n            <p style=\"margin:0 0 15px;color:#4b5563;font-size:14px;line-height:1.6\">\n              Tu póliza <strong>{{numero_poliza}}</strong> está próxima a vencer. Te invitamos a renovarla para mantener tu cobertura activa.\n            </p>\n            <table style=\"width:100%;background:#f9fafb;border-radius:6px;padding:15px;margin:20px 0\">\n              <tr>\n                <td>\n                  <p style=\"margin:0 0 5px;color:#6b7280;font-size:12px\">Fecha de vencimiento</p>\n                  <p style=\"margin:0;color:#111827;font-size:16px;font-weight:600\">{{fecha_vencimiento}}</p>\n                </td>\n              </tr>\n            </table>\n            <table style=\"margin:20px 0;width:100%\">\n              <tr>\n                <td align=\"center\">\n                  <a href=\"#\" style=\"display:inline-block;padding:12px 30px;background:#10b981;color:white;text-decoration:none;border-radius:6px;font-weight:600\">Renovar Ahora</a>\n                </td>\n              </tr>\n            </table>\n          </td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n</table>', 'renovaciones', 'Plantilla para recordar renovaciones de pólizas', '\"{\\\"nombre\\\":\\\"Nombre del cliente\\\",\\\"numero_poliza\\\":\\\"N\\\\u00famero de p\\\\u00f3liza\\\",\\\"fecha_vencimiento\\\":\\\"Fecha de vencimiento\\\"}\"', '\"[\\\"nombre\\\",\\\"numero_poliza\\\",\\\"fecha_vencimiento\\\"]\"', 1, 1, 0, '2025-10-03 22:31:25', '2025-10-03 22:31:25'),
(13, 2, 'Recordatorio', '<table style=\"width:100%;background:#f6f6f6;padding:20px\">\n  <tr>\n    <td align=\"center\">\n      <table style=\"width:600px;background:white;border-radius:8px;padding:30px\">\n        <tr>\n          <td>\n            <div style=\"background:#fef3c7;border-left:4px solid #f59e0b;padding:15px;margin:0 0 20px;border-radius:4px\">\n              <p style=\"margin:0;color:#92400e;font-size:14px;font-weight:600\">⚠️ Recordatorio Importante</p>\n            </div>\n            <p style=\"margin:0 0 15px;color:#4b5563;font-size:14px;line-height:1.6\">\n              Hola <strong>{{nombre}}</strong>,\n            </p>\n            <p style=\"margin:0 0 15px;color:#4b5563;font-size:14px;line-height:1.6\">\n              Te recordamos que tienes una acción pendiente relacionada con tu póliza.\n            </p>\n            <table style=\"margin:20px 0;width:100%\">\n              <tr>\n                <td align=\"center\">\n                  <a href=\"#\" style=\"display:inline-block;padding:12px 30px;background:#635BFF;color:white;text-decoration:none;border-radius:6px;font-weight:600\">Ver Detalles</a>\n                </td>\n              </tr>\n            </table>\n          </td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n</table>', 'recordatorios', 'Plantilla para recordatorios importantes', '\"{\\\"nombre\\\":\\\"Nombre del cliente\\\"}\"', '\"[\\\"nombre\\\"]\"', 1, 1, 0, '2025-10-03 22:31:25', '2025-10-03 22:31:25'),
(14, 2, 'Notificación', '<table style=\"width:100%;background:#f6f6f6;padding:20px\">\n  <tr>\n    <td align=\"center\">\n      <table style=\"width:600px;background:white;border-radius:8px;padding:30px\">\n        <tr>\n          <td>\n            <h2 style=\"margin:0 0 20px;color:#111827;font-size:24px\">Actualización de tu Cuenta</h2>\n            <p style=\"margin:0 0 15px;color:#4b5563;font-size:14px;line-height:1.6\">\n              Hola <strong>{{nombre}}</strong>,\n            </p>\n            <p style=\"margin:0 0 20px;color:#4b5563;font-size:14px;line-height:1.6\">\n              Queremos informarte sobre una actualización importante en tu cuenta.\n            </p>\n            <hr style=\"border:none;border-top:1px solid #e5e7eb;margin:20px 0\" />\n            <p style=\"margin:0;color:#6b7280;font-size:12px;text-align:center\">\n              Si tienes preguntas, contáctanos en soporte@guro.com\n            </p>\n          </td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n</table>', 'notificaciones', 'Plantilla para notificaciones generales', '\"{\\\"nombre\\\":\\\"Nombre del cliente\\\"}\"', '\"[\\\"nombre\\\"]\"', 1, 1, 0, '2025-10-03 22:31:25', '2025-10-03 22:31:25'),
(15, 21, 'renovación', '<table style=\"width:100%;background:#f6f6f6;padding:20px\">\n  <tr>\n    <td align=\"center\">\n      <table style=\"width:600px;background:white;border-radius:8px;padding:30px\">\n        <tr>\n          <td>\n            <h2 style=\"margin:0 0 20px;color:#111827;font-size:24px\">Renovación de Póliza</h2>\n            <p style=\"margin:0 0 15px;color:#4b5563;font-size:14px;line-height:1.6\">\n              Estimado/a <strong>{{nombre}}</strong>,\n            </p>\n            <p style=\"margin:0 0 15px;color:#4b5563;font-size:14px;line-height:1.6\">\n              Tu póliza <strong>{{numero_poliza}}</strong> está próxima a vencer. Te invitamos a renovarla para mantener tu cobertura activa.\n            </p>\n            <table style=\"width:100%;background:#f9fafb;border-radius:6px;padding:15px;margin:20px 0\">\n              <tr>\n                <td>\n                  <p style=\"margin:0 0 5px;color:#6b7280;font-size:12px\">Fecha de vencimiento</p>\n                  <p style=\"margin:0;color:#111827;font-size:16px;font-weight:600\">{{fecha_vencimiento}}</p>\n                </td>\n              </tr>\n            </table>\n            <table style=\"margin:20px 0;width:100%\">\n              <tr>\n                <td align=\"center\">\n                  <a href=\"#\" style=\"display:inline-block;padding:12px 30px;background:#10b981;color:white;text-decoration:none;border-radius:6px;font-weight:600\">Renovar Ahora</a>\n                </td>\n              </tr>\n            </table>\n          </td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n</table>', 'recordatorios', NULL, '\"[\\\"nombre\\\",\\\"numero_poliza\\\",\\\"fecha_vencimiento\\\"]\"', '\"[0,1,2]\"', 1, 0, 0, '2025-10-03 22:40:08', '2025-10-03 22:40:08'),
(17, 21, 'Prueba', '<table style=\"width:100%;background:#f6f6f6;padding:20px;font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif\">\n  <tr>\n    <td align=\"center\">\n      <table style=\"width:600px;background:white;border-radius:8px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.1)\">\n        <tr>\n          <td style=\"background:#635BFF;padding:30px\">\n            <div style=\"text-align:center;margin-bottom:15px\"><img src=\"data:image/png;base64,\" alt=\"Logo\" style=\"max-width:150px;height:auto;display:inline-block\" /></div>\n            <h1 style=\"margin:0 0 10px;color:white;font-size:28px;font-weight:bold;text-align:center\">Bienvenido a GURO</h1>\n            <p style=\"margin:0;color:rgba(255,255,255,0.9);font-size:14px;text-align:center\">Tu plataforma de gestión de seguros</p>\n          </td>\n        </tr>\n        <tr>\n          <td style=\"padding:30px\">\n            <div style=\"color:#4b5563;font-size:14px;line-height:1.6;white-space:pre-wrap;margin-bottom:15px;text-align:left\">Hola {{nombre}},\n\nGracias por confiar en nosotros.</div>\n          </td>\n        </tr>\n        <tr>\n          <td style=\"background:#f9fafb;padding:25px;text-align:center;border-top:1px solid #e5e7eb\">\n            \n            <p style=\"margin:0;color:#6b7280;font-size:12px\">© 2024 GURO. Todos los derechos reservados.</p>\n            <p style=\"margin:10px 0 0;color:#9ca3af;font-size:11px\"><a href=\"{{unsubscribe_link}}\" style=\"color:#9ca3af;text-decoration:underline\">Cancelar suscripción</a></p>\n          </td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n</table>', 'marketing', NULL, '\"[\\\"nombre\\\",\\\"unsubscribe_link\\\"]\"', '\"[0,1]\"', 1, 0, 0, '2025-10-03 23:05:28', '2025-10-03 23:05:28');
